  <script>
    const products = [
      {
        name: "Axiom Over-Ear Headphones",
        category: "Tech",
        label: "Best seller",
        price: "$289",
        compareAt: "$349",
        description: "Spatial audio tuning with matte alloy detailing and 40-hour playback.",
        accent: ["76%", "22%", "110px", "110px", "-10%", "58%"],
        tags: ["Wireless", "Noise canceling", "Midnight black"]
      },
      {
        name: "Helix Lounge Jacket",
        category: "Fashion",
        label: "New drop",
        price: "$198",
        compareAt: "$240",
        description: "A structured knit outer layer with soft-touch lining for evening layering.",
        accent: ["20%", "66%", "120px", "120px", "60%", "14%"],
        tags: ["Limited capsule", "Soft shell", "Unisex"]
      },
      {
        name: "Halo Table Lamp",
        category: "Home",
        label: "Editor pick",
        price: "$164",
        compareAt: "$210",
        description: "Diffuse ambient light through smoked glass and brushed graphite trim.",
        accent: ["72%", "42%", "128px", "128px", "14%", "64%"],
        tags: ["Warm glow", "Glass finish", "Desk or bedside"]
      },
      {
        name: "Arc Modular Shelf",
        category: "Home",
        label: "Studio favorite",
        price: "$320",
        compareAt: "$390",
        description: "Minimal storage geometry with stackable sections and hidden cable routing.",
        accent: ["28%", "24%", "118px", "118px", "52%", "62%"],
        tags: ["Assembly kit", "Modular", "Charcoal"]
      }
    ];

    const deals = [
      {
        name: "Night Mode Desk Set",
        category: "Workspace bundle",
        discount: "28% off",
        price: "$156",
        compareAt: "$218",
        description: "Desk mat, task light, and tray set finished in smoke and graphite tones.",
        badge: "Ends today"
      },
      {
        name: "Motion Knit Runners",
        category: "Footwear",
        discount: "30% off",
        price: "$112",
        compareAt: "$160",
        description: "High-flex sole, monochrome profile, and breathable stretch-knit upper.",
        badge: "Low stock"
      },
      {
        name: "Contour Brew System",
        category: "Kitchen",
        discount: "22% off",
        price: "$179",
        compareAt: "$230",
        description: "Precision temperature control with brushed steel accents and compact form.",
        badge: "Member price"
      }
    ];

    const editorials = [
      {
        title: "The late-hour workspace edit",
        category: "Guide",
        readTime: "6 min read",
        description: "A closer look at building a desk setup that feels calm, focused, and visually refined after dark."
      },
      {
        title: "How to layer texture in a minimal room",
        category: "Journal",
        readTime: "4 min read",
        description: "Balance stone, glass, and matte textiles to create depth without losing the clean silhouette."
      },
      {
        title: "Three capsule wardrobe anchors for the season",
        category: "Style",
        readTime: "5 min read",
        description: "Quiet statement pieces that move across work, travel, and evening settings with ease."
      }
    ];

    const productGrid = document.getElementById("productGrid");
    const dealGrid = document.getElementById("dealGrid");
    const editorialGrid = document.getElementById("editorialGrid");
    const filterChips = document.getElementById("filterChips");

    const categories = ["All", ...new Set(products.map((product) => product.category))];
    let activeCategory = "All";

    function renderMediaMarkup(accent) {
      const [topA, leftA, sizeA, sizeB, topB, leftB] = accent;
      return `
        <div class="orb" style="top:${topA}; left:${leftA}; width:${sizeA}; height:${sizeA};"></div>
        <div class="shape" style="top:${topB}; left:${leftB}; width:${sizeB}; height:${sizeB}; border-radius:28px;"></div>
        <div class="frame" style="top:18%; left:14%; width:72%; height:62%; border-radius:28px;"></div>
        <div class="frame" style="top:30%; left:28%; width:36%; height:28%; border-radius:20px;"></div>
      `;
    }

    function renderFilters() {
      filterChips.innerHTML = categories
        .map((category) => `
          <button
            type="button"
            class="chip ${category === activeCategory ? "active" : ""}"
            data-category="${category}"
          >
            ${category}
          </button>
        `)
        .join("");
    }

    function renderProducts() {
      const visibleProducts = activeCategory === "All"
        ? products
        : products.filter((product) => product.category === activeCategory);

      productGrid.innerHTML = visibleProducts
        .map((product) => `
          <article class="card">
            <div class="card-media">
              <span class="badge">${product.label}</span>
              ${renderMediaMarkup(product.accent)}
            </div>
            <div class="card-body">
              <div class="meta-row">
                <span>${product.category}</span>
                <span>Free shipping</span>
              </div>
              <h3>${product.name}</h3>
              <p class="section-copy">${product.description}</p>
              <div class="price-row">
                <span class="price">${product.price}</span>
                <span class="price-compare">${product.compareAt}</span>
              </div>
              <div class="tag-row">
                ${product.tags.map((tag) => `<span class="tag">${tag}</span>`).join("")}
              </div>
            </div>
          </article>
        `)
        .join("");
    }

    function renderDeals() {
      dealGrid.innerHTML = deals
        .map((deal, index) => `
          <article class="deal-card">
            <div class="deal-media">
              <span class="badge">${deal.badge}</span>
              ${renderMediaMarkup([
                `${28 + index * 14}%`,
                `${18 + index * 12}%`,
                `${110 + index * 8}px`,
                `${124 - index * 6}px`,
                `${16 + index * 10}%`,
                `${52 - index * 8}%`
              ])}
            </div>
            <div class="deal-body">
              <div class="meta-row">
                <span>${deal.category}</span>
                <span style="color: var(--success); text-decoration: none;">${deal.discount}</span>
              </div>
              <h3>${deal.name}</h3>
              <p class="section-copy">${deal.description}</p>
              <div class="deal-price">
                <strong>${deal.price}</strong>
                <span>${deal.compareAt}</span>
              </div>
            </div>
          </article>
        `)
        .join("");
    }

    function renderEditorials() {
      editorialGrid.innerHTML = editorials
        .map((story, index) => `
          <article class="editorial-card">
            <div class="editorial-media">
              <span class="badge">${story.category}</span>
              ${renderMediaMarkup([
                `${24 + index * 16}%`,
                `${22 + index * 10}%`,
                `${108 + index * 10}px`,
                `${120 + index * 8}px`,
                `${48 - index * 5}%`,
                `${54 - index * 8}%`
              ])}
            </div>
            <div class="editorial-body">
              <div class="editorial-meta" style="text-decoration: none;">${story.readTime}</div>
              <h3>${story.title}</h3>
              <p class="section-copy">${story.description}</p>
            </div>
          </article>
        `)
        .join("");
    }

    function updateCountdown() {
      const target = new Date();
      target.setHours(23, 59, 59, 999);

      const now = new Date();
      const diff = Math.max(target - now, 0);

      const hours = Math.floor(diff / (1000 * 60 * 60));
      const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
      const seconds = Math.floor((diff % (1000 * 60)) / 1000);

      document.getElementById("hours").textContent = String(hours).padStart(2, "0");
      document.getElementById("minutes").textContent = String(minutes).padStart(2, "0");
      document.getElementById("seconds").textContent = String(seconds).padStart(2, "0");
    }

    filterChips.addEventListener("click", (event) => {
      const button = event.target.closest("[data-category]");
      if (!button) return;
      activeCategory = button.dataset.category;
      renderFilters();
      renderProducts();
    });

    document.querySelector(".newsletter-form").addEventListener("submit", (event) => {
      event.preventDefault();
      const input = document.getElementById("email");
      const button = event.currentTarget.querySelector("button");
      if (!input.value.trim()) {
        input.focus();
        return;
      }

      button.textContent = "Subscribed";
      button.disabled = true;
      input.value = "";
    });

    renderFilters();
    renderProducts();
    renderDeals();
    renderEditorials();
    updateCountdown();
    setInterval(updateCountdown, 1000);
  </script>
</body>
